"""Export a compact, privacy-conscious Anki schema for card generation."""
from __future__ import annotations

from pathlib import Path

from .ankiconnect import AnkiConnect

MANUAL_MARKER = "## Field meanings and generation rules (manual)"


def build_collection_config(anki: AnkiConnect) -> str:
    lines = [
        "# Anki Collection Configuration",
        "",
        "<!-- Generated from the connected Anki collection. Do not edit the generated section. -->",
        "",
        "## Decks",
        "",
    ]
    for deck in sorted(anki.deck_names(), key=str.casefold):
        lines.append(f"- `{deck}`")

    lines += ["", "## Note types and fields", ""]
    for note_type in sorted(anki.model_names(), key=str.casefold):
        fields = anki.model_field_names(note_type)
        templates = anki.model_templates(note_type)
        lines += [f"### {note_type}", "", "Fields (use these exact names):"]
        lines.extend(f"- `{field}`" for field in fields)
        lines += ["", "Card templates generated by Anki:"]
        lines.extend(f"- `{name}`" for name in templates)
        lines.append("")

    return "\n".join(lines).rstrip() + "\n"


def refresh_collection_config(anki: AnkiConnect, path: str | Path) -> Path:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    existing = target.read_text(encoding="utf-8") if target.exists() else ""
    manual = ""
    if MANUAL_MARKER in existing:
        manual = existing[existing.index(MANUAL_MARKER):].strip()
    if not manual:
        manual = (
            f"{MANUAL_MARKER}\n\n"
            "For each note type, explain what each field means, the preferred language and format, "
            "and which decks should receive each kind of card. Keep these notes free of credentials."
        )
    target.write_text(build_collection_config(anki).rstrip() + "\n\n" + manual + "\n", encoding="utf-8")
    return target
